import 'package:flutter/material.dart';import '../services/progress_store.dart';import '../widgets/ui.dart';
class SkinsScreen extends StatelessWidget{final ProgressStore store;const SkinsScreen({super.key,required this.store});@override Widget build(BuildContext c)=>AnimatedBuilder(animation:store,builder:(c,_){final cs=[cyan,purple,orange,green],ns=['ION','VOID','EMBER','NOVA'],cost=[0,12,30,60];return Scaffold(appBar:AppBar(title:const Text('ROBOT SHELLS')),body:ListView(padding:const EdgeInsets.all(22),children:[const NeonTitle('SKINS'),Text('${store.stars} stars recovered',style:const TextStyle(color:muted)),const SizedBox(height:20),for(int i=0;i<4;i++)Container(margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:panel,borderRadius:BorderRadius.circular(20),border:Border.all(color:store.skin==i?cs[i]:cs[i].withOpacity(.2))),child:Row(children:[Icon(Icons.smart_toy,color:cs[i],size:40),const SizedBox(width:15),Expanded(child:Text('${ns[i]}  •  ${i==0?'DEFAULT':'${cost[i]} STARS'}',style:const TextStyle(fontWeight:FontWeight.w900))),if(store.stars>=cost[i])TextButton(onPressed:()=>store.setSkin(i),child:Text(store.skin==i?'EQUIPPED':'EQUIP'))else const Icon(Icons.lock,color:muted)]))]));});}
